+fn probe_lock_holders(lock_path: &Path) -> TestResult {
+    for process in std::fs::read_dir("/proc")? {
+        let process = process?;
+        let pid = process.file_name();
+        let Some(pid_text) = pid.to_str() else {
+            continue;
+        };
+        if !pid_text.bytes().all(|byte| byte.is_ascii_digit()) {
+            continue;
+        }
+        let fd_dir = process.path().join("fd");
+        let Ok(descriptors) = std::fs::read_dir(fd_dir) else {
+            continue;
+        };
+        for descriptor in descriptors.flatten() {
+            let Ok(target) = std::fs::read_link(descriptor.path()) else {
+                continue;
+            };
+            if target != lock_path {
+                continue;
+            }
+            let cmdline = std::fs::read(process.path().join("cmdline")).unwrap_or_default();
+            let cmdline = String::from_utf8_lossy(&cmdline).replace('\0', " ");
+            let status = std::fs::read_to_string(process.path().join("status"))
+                .unwrap_or_else(|error| format!("status unreadable: {error}"));
+            let status = status
+                .lines()
+                .filter(|line| {
+                    ["Name:", "State:", "PPid:", "Threads:"]
+                        .iter()
+                        .any(|prefix| line.starts_with(prefix))
+                })
+                .collect::<Vec<_>>()
+                .join("; ");
+            eprintln!(
+                "PROBE holder pid={pid_text} fd={} cmdline={cmdline:?} status={status}",
