1	use std::path::Path;
2	use std::time::{Duration, Instant};
3	
4	use haematite::{Database, DatabaseError};
5	
6	/// Caller-owned ruling for retrying a transient data-directory writer lock.
7	///
8	/// Both spans are required because the acceptable boot delay and the retry
9	/// cadence are deployment decisions. A retry is attempted only after
10	/// haematite returns [`DatabaseError::DataDirLocked`]; every other open error
11	/// is returned immediately.
12	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
13	pub struct LockAcquisitionRuling {
14	    patience: Duration,
15	    retry_cadence: Duration,
16	}
17	
18	impl LockAcquisitionRuling {
19	    /// State the maximum acquisition span and the cadence between attempts.
20	    #[must_use]
21	    pub const fn new(patience: Duration, retry_cadence: Duration) -> Self {
22	        Self {
23	            patience,
24	            retry_cadence,
25	        }
26	    }
27	}
28	
29	pub(crate) fn open_database(
30	    data_dir: &Path,
31	    ruling: LockAcquisitionRuling,
32	) -> Result<Database, DatabaseError> {
33	    let started = Instant::now();
34	    loop {
35	        match Database::open(data_dir) {
36	            Ok(database) => return Ok(database),
37	            Err(error @ DatabaseError::DataDirLocked { .. }) => {
38	                let elapsed = started.elapsed();
39	                if elapsed >= ruling.patience {
40	                    return Err(error);
41	                }
42	                let remaining = ruling.patience.saturating_sub(elapsed);
43	                // This is the caller-ruled cadence between real lock attempts,
44	                // not a sleep used as synchronization. Acquisition returns on
45	                // the first successful try and never waits past the patience.
46	                std::thread::sleep(ruling.retry_cadence.min(remaining));
47	            }
48	            Err(error) => return Err(error),
49	        }
50	    }
51	}

